def schedule_slots(start,end,duration,busy):
 if any(type(x)is not int for x in (start,end,duration)) or not 0<=start<=10000000 or not 0<=end<=10000000 or not 1<=duration<=10000000 or start>end:return None
 if any(len(x)!=2 or any(type(v)is not int or not 0<=v<=10000000 for v in x) or x[0]>x[1] for x in busy):return None
 a=sorted((max(start,x),min(end,y)) for x,y in busy if y>start and x<end);m=[]
 for x,y in a:
  if m and x<=m[-1][1]:m[-1][1]=max(m[-1][1],y)
  else:m.append([x,y])
 o=[];p=start
 for x,y in m+[[end,end]]:
  while p<=10000000-duration and p+duration<=x:o.append(p);p+=duration
  p=max(p,y)
 return o
